import {
  ArrowLeft, ArrowRight, Bell, Building2, CalendarDays, Check, ChevronDown, CircleDollarSign,
  ClipboardList, Clock3, Copy, Download, FileCheck2, FileText, Filter, Hotel as HotelIcon,
  Link2, ListFilter, LogIn, LogOut, LockKeyhole, Menu, MoreHorizontal, Pencil, Plus, RefreshCw, Save, Search, Send, Settings, Share2,
  Sparkles, TrainFront, Trash2, TrendingUp, UserRound, UsersRound, X, Zap,
} from "lucide-react";
